def max_rects(grid, color):
    """All maximal solid rectangles of a color via histogram method."""
    h,w=len(grid),len(grid[0])
    m=[[1 if grid[i][j]==color else 0 for j in range(w)] for i in range(h)]
    heights=[0]*w; best=None
    for i in range(h):
        for j in range(w):
            heights[j]=heights[j]+1 if m[i][j] else 0
        st=[]
        for j in range(w+1):
            cur=heights[j] if j<w else 0
            start=j
            while st and st[-1][1]>=cur:
                s,hh=st.pop(); area=hh*(j-s)
                if best is None or area>best[0]: best=(area,i-hh+1,s,hh,j-s)
                start=s
            st.append((start,cur))
    return best

def recolor_largest_rects(grid, new=4, min_area=9):
    """Each color's largest solid same-color rectangle (area >= min_area) becomes new."""
    g=[row[:] for row in grid]
    for c in sorted({v for row in grid for v in row}):
        r=max_rects(grid,c)
        if r and r[0]>=min_area:
            _,top,left,h,w=r
            for i in range(top,top+h):
                for j in range(left,left+w): g[i][j]=new
    return g

